	private static LmdbStore gatedStore(Path directory, LmdbStoreConfig config, Gate gate) {
		return new LmdbStore(directory.toFile(), config) {
			@Override
			LmdbSailStore createBackingStore(File dataDir, StoreProperties properties, LmdbStoreConfig selected,
					boolean estimatorEnabled) throws IOException, SailException {
				gate.properties.set(properties);
				if (gate.boundary == Boundary.AFTER_DISCOVERY) {
					gate.hold();
				}
				return new LmdbSailStore(dataDir, properties, selected, estimatorEnabled,
						(valueDir, valueProperties, valueConfig) -> {
							gate.qualifiedBeforeValue = valueProperties.rdfTermDomainQualifiedAtOpen;
							VALUE_GATE.set(gate);
							try {
								ValueStore value = new GatedValueStore(valueDir, valueProperties, valueConfig);
								gate.value.set(value);
								return value;
							} finally {
								VALUE_GATE.remove();
							}
						},
						(tripleDir, tripleProperties, tripleConfig, values) -> new TripleStore(tripleDir,
								tripleProperties, tripleConfig, values, new TripleStore.EnvironmentLifecycle() {
									@Override
									public void afterOpen(long env) throws IOException {
										if (gate.boundary == Boundary.AFTER_TRIPLE_ENVIRONMENT_OPEN) {
											gate.hold();
										}
									}

									@Override
									public void close(long env) {
										gate.tripleClosed.incrementAndGet();
										mdb_env_close(env);
									}
								}));
			}
		};
	}

	private static final class Gate {
		final Boundary boundary;
		final CountDownLatch entered = new CountDownLatch(1);
		final CountDownLatch release = new CountDownLatch(1);
		final AtomicReference<StoreProperties> properties = new AtomicReference<>();
		final AtomicReference<ValueStore> value = new AtomicReference<>();
		final AtomicInteger tripleClosed = new AtomicInteger();
		final AtomicBoolean armed = new AtomicBoolean(true);
		volatile boolean qualifiedBeforeValue;
		volatile long valueObserved = -1;

		Gate(Boundary boundary) {
			this.boundary = boundary;
		}

		void hold() throws IOException {
			entered.countDown();
			try {
				if (!release.await(30, TimeUnit.SECONDS)) {
					throw new IOException("startup admission gate was not released");
				}
			} catch (InterruptedException interrupted) {
				Thread.currentThread().interrupt();
				throw new IOException("startup admission gate interrupted", interrupted);
			}
		}
	}

	private static final class GatedValueStore extends ValueStore {
		GatedValueStore(File directory, StoreProperties properties, LmdbStoreConfig config) throws IOException {
			super(directory, properties, config, false, null, LmdbStoreFormat.fromProperties(properties, config), true);
		}

		@Override
		long lastTransactionId() throws IOException {
			long observed = super.lastTransactionId();
			Gate gate = VALUE_GATE.get();
			if (gate != null && gate.boundary == Boundary.AFTER_VALUE_GENERATION_READ
					&& StackWalker.getInstance()
							.walk(frames -> frames
									.anyMatch(frame -> frame.getClassName().equals(ValueStore.class.getName())
											&& frame.getMethodName().equals("beginStartupInitialization")))
					&& gate.armed.compareAndSet(true, false)) {
				gate.value.set(this);
				gate.valueObserved = observed;
				gate.hold();
			}
			return observed;
		}
	}

	private static void seed(Path directory, LmdbStoreConfig config) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			try (var connection = repository.getConnection()) {
				connection.begin();
				connection.add(S, P, O);
				connection.add(OTHER, P, VF.createLiteral("removed"));
				connection.setNamespace("original", "urn:original:");
				connection.commit();
				connection.begin();
				connection.remove(OTHER, P, VF.createLiteral("removed"));
				connection.commit();
			}
		} finally {
			repository.shutDown();
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc").setInlineLiterals(false)
				.setForceSync(true)
				.setSketchEstimatorEnabled(false)
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
				.setPredicateGuaranteeIndexEnabled(true)
				.setPredicateGuaranteeIndexAutoRebuild(true);
	}

	private static String causeText(Throwable failure) {
		StringBuilder text = new StringBuilder();
		while (failure != null) {
			text.append(failure).append('\n');
			failure = failure.getCause();
		}
		return text.toString();
	}

	/** Runs in a separate process, using supported metadata encodings and one native environment owner. */
	public static final class ForeignWriter {
		public static void main(String[] args) throws Exception {
			long env = 0;
			try (MemoryStack stack = MemoryStack.stackPush()) {
				PointerBuffer handle = stack.mallocPointer(1);
				E(mdb_env_create(handle));
				env = handle.get(0);
				E(mdb_env_set_maxdbs(env, 128));
				E(mdb_env_open(env, args[0], MDB_NOTLS, 0664));
				long before = LmdbUtil.readTransaction(env, (inner, txn) -> mdb_txn_id(txn));
				final String kind = args[1];
				LmdbUtil.writeTransaction(env, (inner, txn) -> {
					IntBuffer dbi = inner.mallocInt(1);
					String database = kind.equals("values") ? "gc_meta" : TripleStore.NAMESPACE_DATABASE_NAME;
					E(mdb_dbi_open(txn, database, 0, dbi));
					byte[] keyBytes = kind.equals("values") ? ReferenceCountProof.GENERATION_KEY
							: TripleStore.NAMESPACE_SNAPSHOT_KEY;
					MDBVal key = MDBVal.calloc(inner).mv_data(inner.bytes(keyBytes));
					MDBVal data = MDBVal.calloc(inner);
					int found = mdb_get(txn, dbi.get(0), key, data);
					if (found != MDB_SUCCESS) {
						throw new IOException("required existing metadata was not found: " + found);
					}
					byte[] old = new byte[(int) data.mv_size()];
					data.mv_data().duplicate().get(old);
					byte[] next;
					if (kind.equals("values")) {
						if (old.length != ReferenceCountProof.GENERATION_BYTES) {
							throw new IOException("invalid reference-count generation length");
						}
						next = old.clone();
						next[0] ^= 1;
					} else {
						next = NamespaceStore.encodeSnapshot(Map.of("foreign", "urn:foreign:"));
						if (Arrays.equals(old, next)) {
							throw new IOException("namespace mutation must change the real snapshot");
						}
					}
					data.mv_data(inner.bytes(next));
					E(mdb_put(txn, dbi.get(0), key, data, 0));
					return null;
				});
				long after = LmdbUtil.readTransaction(env, (inner, txn) -> mdb_txn_id(txn));
				System.out.println("FOREIGN_COMMITTED " + before + " " + after);
			} finally {
				if (env != 0) {
					mdb_env_close(env);
				}
			}
		}
	}
